mapper.select:
SELECT 
FROM TBL_AR_TODO
WHERE IS_DELETED = 0

    AND HANDLER_ID = #{handlerId}


    AND TODO_STATUS = #{todoStatus}


    AND TENANT_ID = #{tenantId}

ORDER BY PRIORITY DESC, DUE_DATE ASC

SELECT 
FROM TBL_AR_TODO
WHERE IS_DELETED = 0
    AND BUSINESS_TYPE = #{businessType}
    AND BUSINESS_ID = #{businessId}

SELECT COUNT(1) as totalCount, SUM(CASE WHEN TODO_STATUS = 0 THEN 1 ELSE 0 END) as pendingCount, SUM(CASE WHEN TODO_STATUS = 1 THEN 1 ELSE 0 END) as completedCount, SUM(CASE WHEN TODO_STATUS = 0 AND DUE_DATE < SYSDATE THEN 1 ELSE 0 END) as overdueCount FROM TBL_AR_TODO WHERE IS_DELETED = 0
AND HANDLER_ID = #{handlerId}
AND TENANT_ID = #{tenantId}

mapper.delete:
DELETE FROM TBL_AR_TODO
WHERE TENANT_ID = #{tenantId}
    AND TODO_STATUS = 1
    AND COMPLETE_TIME < SYSDATE - #{beforeDays}
